package com.gamehub.application.service; import com.gamehub.application.UserService; import com.gamehub.domain.User; import com.gamehub.infrastructure.CustomerRepository; import java.util.List; public final class AccountService { private final UserService users; private final CustomerRepository customers; public AccountService(UserService users,CustomerRepository customers){this.users=users;this.customers=customers;} public List<String> customers()throws Exception{return customers.records();} public User authenticate(String login,String password)throws Exception{if(login==null||login.isBlank())throw new IllegalArgumentException("Login is required");return users.authenticate(login,password);} public User register(String n,String e,String ph,String p,String c)throws Exception{if(!p.equals(c))throw new IllegalArgumentException("Passwords do not match");return users.registerCustomer(n,e,ph,p);} }
